   241	// TagCommit resolves an annotated or lightweight tag to the commit it points
   242	// at. The bool reports whether the tag exists locally at all, so a caller can
   243	// tell "no such tag" from a genuine failure to read it.
   244	func (g Client) TagCommit(ctx context.Context, name string) (string, bool, error) {
   245		// ^{commit} dereferences an annotated tag to its commit; without it the
   246		// answer would be the tag object's own sha, which never matches a commit.
   247		sha, err := g.run(ctx, "rev-parse", "--verify", "--quiet", "refs/tags/"+name+"^{commit}")
   248		if err == nil {
   249			return sha, sha != "", nil
   250		}
   251		// --quiet makes an unknown ref exit 1 with no output, which is the answer
   252		// rather than a failure.
   253		if ee, ok := errors.AsType[*command.ExitError](err); ok && ee.Code == 1 {
   254			return "", false, nil
   255		}
   256		return "", false, fmt.Errorf("resolve tag %s: %w", name, err)
   257	}
