   352	// PushRejectedError reports that the remote refused the push because it has
   353	// commits we do not have.
   354	type PushRejectedError struct {
   355		Remote  string
   356		Refspec string
   357		Stderr  string
   358	}
   359	
   360	func (e *PushRejectedError) Error() string {
   361		return fmt.Sprintf("push to %s was rejected: %s", e.Remote, strings.TrimSpace(e.Stderr))
   362	}
   363	
   364	// isRejection recognises a non-fast-forward refusal. git has no distinct exit
   365	// code for it, so the message is the only signal available; the phrases below
   366	// are the ones git itself emits.
   367	func isRejection(stderr string) bool {
   368		for _, marker := range []string{"[rejected]", "non-fast-forward", "fetch first", "Updates were rejected"} {
   369			if strings.Contains(stderr, marker) {
   370				return true
   371			}
   372		}
   373		return false
   374	}
