   376	// Rebase replays the current branch onto upstream.
   377	//
   378	// A conflict is reported as *RebaseConflictError with the rebase left in
   379	// progress, so the caller can decide — this package must not abort on the
   380	// caller's behalf, because whether a conflict is recoverable is policy.
   381	func (g Client) Rebase(ctx context.Context, upstream string) error {
   382		_, err := g.run(ctx, "rebase", upstream)
   383		if err == nil {
   384			return nil
   385		}
   386		if ee, ok := errors.AsType[*command.ExitError](err); ok {
   387			return &RebaseConflictError{Upstream: upstream, Stderr: ee.Stderr}
   388		}
   389		return fmt.Errorf("rebase onto %s: %w", upstream, err)
   390	}
